import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicValues {
    dialogOpen: boolean
    dismissedKey: string | null
    inlinePanelCount: number
    inlinePanelMounted: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicActions {
    claimInlinePanel: () => {
        value: true
    }
    closeDialog: () => {
        value: true
    }
    dismiss: (key: string) => {
        key: string
    }
    openDialog: () => {
        value: true
    }
    releaseInlinePanel: () => {
        value: true
    }
    restore: () => {
        value: true
    }
}

export interface wizardSyncUiLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        inlinePanelMounted: (inlinePanelCount: number) => boolean
    }
}

export type wizardSyncUiLogicType = MakeLogicType<
    wizardSyncUiLogicValues,
    wizardSyncUiLogicActions,
    Record<string, any>,
    wizardSyncUiLogicMeta
>

/**
 * UI state for the detached wizard sync widget, shared app-wide (mounted by WizardSyncFab):
 *   - `dismissedKey`: the run the user minimized. Keyed by run id (cloud) or session id (local) so a
 *     fresh run is never born already-minimized, and a minimize survives navigation (persisted).
 *   - `dialogOpen`: whether the "all the details" dialog is showing.
 *   - `inlinePanelMounted`: a scene is already showing this run inline (the onboarding install step,
 *     the inbox), so the detached surfaces stand down rather than showing it twice. Refcounted:
 *     a boolean would let one panel's unmount un-hide the widget while another is still showing.
 *
 * The widget itself owns no run data; the per-mode inner components feed it the normalized progress.
 */
export const wizardSyncUiLogic = kea<wizardSyncUiLogicType>([
    path(['scenes', 'onboarding', 'wizardSyncUiLogic']),
    actions({
        dismiss: (key: string) => ({ key }),
        restore: true,
        openDialog: true,
        closeDialog: true,
        claimInlinePanel: true,
        releaseInlinePanel: true,
    }),
    reducers({
        dismissedKey: [
            null as string | null,
            { persist: true },
            {
                dismiss: (_, { key }) => key,
                restore: () => null,
            },
        ],
        dialogOpen: [
            false,
            {
                openDialog: () => true,
                closeDialog: () => false,
                restore: () => false,
            },
        ],
        inlinePanelCount: [
            0,
            {
                claimInlinePanel: (state) => state + 1,
                releaseInlinePanel: (state) => Math.max(0, state - 1),
            },
        ],
    }),
    selectors({
        inlinePanelMounted: [(s) => [s.inlinePanelCount], (inlinePanelCount: number): boolean => inlinePanelCount > 0],
    }),
])
